// GENERATED by tools/build-shared.js from apps-script/ProductOptions.gs - do not edit here.
/**
 * Product options and variant combinations. (Owner request, Oct 2026.)
 *
 * ONE SOURCE, TWO PLACES - like ListingRules.gs: the backend validates and
 * reconciles with these functions on every save, and `npm run build` copies
 * this file to assets/js/product-options.js so the seller form and the product
 * page use the very same rules. Never edit the copy. Plain functions and `var`
 * only - no Apps Script services, no DOM.
 *
 * THE MODEL
 *   A product is one of:
 *     'single'   one price, one stock count, no choices (bottled water).
 *     'options'  the seller defines option types - Colour, Size or anything
 *                they name ("Package Size", "Design") - each with values.
 *                Every sellable combination is one row in the Variants sheet,
 *                with its own price, stock, SKU and photos.
 *     ''         a listing saved before options existed: a plain list of
 *                "varieties" with a free-text label each. Untouched - it keeps
 *                working exactly as before until the seller converts it.
 *
 *   Options live on the product (Products.OptionsJson):
 *     [{ id: 'o_ab12', name: 'Colour', kind: 'colour', values: [{ id: 'v_cd34', label: 'Red', hex: '#c62828' }] }, ...]
 *   Each variant says which value it has for each option
 *   (Variants.OptionValuesJson, e.g. {"o_ab12": "v_cd34", "o_ef56": "v_gh78"}).
 *
 * IDENTITY. A variant is its VariantId - never its label or price. Option and
 * value ids are stable too, so renaming "Red" to "Crimson" renames every red
 * variant without creating new ones, and an order placed for the old name
 * keeps its own snapshot. The combination key ("o_ab12=v_cd34|o_ef56=v_gh78")
 * is what stops two variants from claiming the same combination.
 *
 * NOTHING IS DELETED. A combination the seller turns off, or whose value they
 * remove, keeps its row with Status 'disabled' - its stock history, open
 * orders and photos stay attached - and simply can't be bought.
 */

// Defaults. The backend can raise or lower them with Script Properties
// (PRODUCT_OPTION_TYPES_MAX, PRODUCT_OPTION_VALUES_MAX,
// PRODUCT_VARIANTS_MAX); the browser only uses them to warn early.
var PRODUCT_OPTION_LIMITS = { types: 3, values: 20, variants: 100, nameMax: 30, labelMax: 30 };

var OPTION_KINDS = ['colour', 'size', 'custom'];
var OPTION_ID_RE = /^o_[a-z0-9]{2,20}$/;
var VALUE_ID_RE = /^v_[a-z0-9]{2,20}$/;
var OPTION_HEX_RE = /^#[0-9a-fA-F]{6}$/;

function optionText(value) {
  return String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
}

/**
 * Checks and cleans a seller's option definitions.
 * Returns { ok: true, options } or { ok: false, error, field }.
 * `field` names what to highlight: 'option:<i>' or 'value:<i>:<j>'.
 */
function validateProductOptions(raw, limits) {
  limits = limits || PRODUCT_OPTION_LIMITS;
  if (!Array.isArray(raw) || raw.length === 0) return { ok: false, error: 'Add at least one option, such as Colour or Size.', field: 'options' };
  if (raw.length > limits.types) return { ok: false, error: 'Use at most ' + limits.types + ' option types.', field: 'options' };
  var seenNames = {}, seenIds = {}, seenValueIds = {};
  var out = [];
  for (var i = 0; i < raw.length; i++) {
    var o = raw[i] || {};
    var name = optionText(o.name);
    var id = String(o.id || '');
    var kind = OPTION_KINDS.indexOf(String(o.kind)) !== -1 ? String(o.kind) : 'custom';
    if (!name) return { ok: false, error: 'Give every option a name, such as Colour or Size.', field: 'option:' + i };
    if (name.length > limits.nameMax) return { ok: false, error: 'Keep option names to ' + limits.nameMax + ' characters.', field: 'option:' + i };
    if (/[<>]/.test(name)) return { ok: false, error: 'Option names cannot contain < or >.', field: 'option:' + i };
    if (seenNames[name.toLowerCase()]) return { ok: false, error: 'There are two options called "' + name + '".', field: 'option:' + i };
    if (!OPTION_ID_RE.test(id) || seenIds[id]) return { ok: false, error: 'Option "' + name + '" is malformed. Please reload and try again.', field: 'option:' + i };
    seenNames[name.toLowerCase()] = true;
    seenIds[id] = true;
    var values = Array.isArray(o.values) ? o.values : [];
    if (!values.length) return { ok: false, error: 'Add at least one value to "' + name + '".', field: 'option:' + i };
    if (values.length > limits.values) return { ok: false, error: '"' + name + '" can have at most ' + limits.values + ' values.', field: 'option:' + i };
    var seenLabels = {};
    var cleanValues = [];
    for (var j = 0; j < values.length; j++) {
      var v = values[j] || {};
      var label = optionText(v.label);
      var vid = String(v.id || '');
      if (!label) return { ok: false, error: 'A value of "' + name + '" is empty.', field: 'value:' + i + ':' + j };
      if (label.length > limits.labelMax) return { ok: false, error: 'Keep values to ' + limits.labelMax + ' characters.', field: 'value:' + i + ':' + j };
      if (/[<>]/.test(label)) return { ok: false, error: 'Values cannot contain < or >.', field: 'value:' + i + ':' + j };
      if (seenLabels[label.toLowerCase()]) return { ok: false, error: '"' + name + '" has "' + label + '" twice.', field: 'value:' + i + ':' + j };
      if (!VALUE_ID_RE.test(vid) || seenValueIds[vid]) return { ok: false, error: 'Value "' + label + '" is malformed. Please reload and try again.', field: 'value:' + i + ':' + j };
      seenLabels[label.toLowerCase()] = true;
      seenValueIds[vid] = true;
      var clean = { id: vid, label: label };
      if (kind === 'colour' && v.hex && OPTION_HEX_RE.test(String(v.hex))) clean.hex = String(v.hex).toLowerCase();
      cleanValues.push(clean);
    }
    out.push({ id: id, name: name, kind: kind, values: cleanValues });
  }
  var count = countOptionCombinations(out);
  if (count > limits.variants) {
    return { ok: false, error: 'These options make ' + count + ' combinations - the most is ' + limits.variants + '. Remove some values, or list very different items separately.', field: 'options' };
  }
  return { ok: true, options: out };
}

function countOptionCombinations(options) {
  return (options || []).reduce(function (n, o) { return n * Math.max(1, (o.values || []).length); }, 1);
}

/**
 * The canonical key of a combination, or '' if it is incomplete or names a
 * value that does not exist. values: { optionId: valueId }.
 */
function optionComboKey(values, options) {
  if (!values || typeof values !== 'object') return '';
  var parts = [];
  for (var i = 0; i < options.length; i++) {
    var o = options[i];
    var vid = values[o.id];
    if (!vid || !o.values.some(function (v) { return v.id === vid; })) return '';
    parts.push(o.id + '=' + vid);
  }
  // A value for an option that is not part of the product makes it invalid too.
  var extra = Object.keys(values).some(function (k) { return !options.some(function (o) { return o.id === k; }); });
  return extra ? '' : parts.join('|');
}

/** "Red / M" - the label every older screen (cart, inventory, orders) shows. */
function optionComboLabel(values, options) {
  return options.map(function (o) {
    var vid = values && values[o.id];
    var v = o.values.filter(function (x) { return x.id === vid; })[0];
    return v ? v.label : '?';
  }).join(' / ');
}

/** Every combination of the options, in option order: [{ optionId: valueId }]. */
function generateOptionCombinations(options) {
  var combos = [{}];
  (options || []).forEach(function (o) {
    var next = [];
    combos.forEach(function (c) {
      o.values.forEach(function (v) {
        var copy = {};
        Object.keys(c).forEach(function (k) { copy[k] = c[k]; });
        copy[o.id] = v.id;
        next.push(copy);
      });
    });
    combos = next;
  });
  return combos;
}

/**
 * What a save would do to the variants of a product, so the seller can be
 * shown it before anything changes and the backend applies exactly the same.
 *
 *   existing: [{ variantId, values, status }]   (rows already in the sheet)
 *   incoming: [{ variantId?, values, active }]  (what the seller is saving)
 *
 * Returns { ok, error, rows: [{ variantId, key, values, label, active, action }] , disabled: [...] }
 *   action: 'create'  a new combination
 *           'update'  an existing variant kept (renames, price, stock...)
 *           'disable' an existing variant the seller switched off
 *   disabled lists existing variants not in the save at all - they are
 *   switched off, never deleted.
 */
function planVariantChanges(options, existing, incoming) {
  var byId = {}, byKey = {};
  (existing || []).forEach(function (e) {
    byId[e.variantId] = e;
    var k = optionComboKey(e.values, options);
    if (k && e.status !== 'deleted' && !byKey[k]) byKey[k] = e;
  });
  var seenKeys = {}, usedIds = {};
  var rows = [];
  for (var i = 0; i < (incoming || []).length; i++) {
    var inc = incoming[i] || {};
    var key = optionComboKey(inc.values, options);
    if (!key) return { ok: false, error: 'Variant ' + (i + 1) + ' does not have a value for every option.', index: i };
    if (seenKeys[key]) return { ok: false, error: optionComboLabel(inc.values, options) + ' is listed twice.', index: i };
    seenKeys[key] = true;
    var match = null;
    if (inc.variantId) {
      match = byId[inc.variantId];
      if (!match || match.status === 'deleted') return { ok: false, error: 'Variant ' + (i + 1) + ' is not part of this product. Please reload and try again.', index: i };
    } else if (byKey[key]) {
      // Regenerated without ids: reuse the variant already holding this
      // combination rather than creating a duplicate.
      match = byKey[key];
    }
    if (match && usedIds[match.variantId]) return { ok: false, error: optionComboLabel(inc.values, options) + ' is listed twice.', index: i };
    if (match) usedIds[match.variantId] = true;
    var active = inc.active !== false;
    rows.push({
      variantId: match ? match.variantId : '',
      key: key,
      values: inc.values,
      label: optionComboLabel(inc.values, options),
      active: active,
      action: !match ? 'create' : (active ? 'update' : 'disable')
    });
  }
  var disabled = (existing || []).filter(function (e) { return !usedIds[e.variantId] && e.status === 'active'; })
    .map(function (e) { return { variantId: e.variantId, label: e.label || '', action: 'disable' }; });
  if (!rows.some(function (r) { return r.active; })) return { ok: false, error: 'Switch on at least one combination that you sell.', index: -1 };
  return { ok: true, rows: rows, disabled: disabled };
}

/* ---------- Shopper side: availability ---------- */

/**
 * What can be chosen for one option, given the other choices made so far.
 * variants: public variants [{ variantId, values, price, stockQty }] - only
 * the ones on sale (disabled combinations are never sent to shoppers).
 * Returns { valueId: 'available' | 'soldout' | 'none' }:
 *   available  at least one matching variant has stock (or is untracked)
 *   soldout    matching variants exist but none has stock
 *   none       no such combination is sold
 */
function optionValueStates(options, variants, optionId, picked) {
  var opt = options.filter(function (o) { return o.id === optionId; })[0];
  var out = {};
  if (!opt) return out;
  opt.values.forEach(function (val) {
    var state = 'none';
    (variants || []).forEach(function (v) {
      if (!v.values || v.values[optionId] !== val.id) return;
      var fits = Object.keys(picked || {}).every(function (k) { return k === optionId || !picked[k] || v.values[k] === picked[k]; });
      if (!fits) return;
      var inStock = v.stockQty == null || v.stockQty > 0;
      if (inStock) state = 'available';
      else if (state === 'none') state = 'soldout';
    });
    out[val.id] = state;
  });
  return out;
}

/** The variant exactly matching a full selection, or null. */
function variantForSelection(options, variants, picked) {
  var key = optionComboKey(picked, options);
  if (!key) return null;
  return (variants || []).filter(function (v) { return optionComboKey(v.values, options) === key; })[0] || null;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { validateProductOptions: validateProductOptions, optionComboKey: optionComboKey, optionComboLabel: optionComboLabel,
    generateOptionCombinations: generateOptionCombinations, planVariantChanges: planVariantChanges, optionValueStates: optionValueStates,
    variantForSelection: variantForSelection, countOptionCombinations: countOptionCombinations, PRODUCT_OPTION_LIMITS: PRODUCT_OPTION_LIMITS };
}
